  const MAYBE_GREEN = STRIPE('#f7fcf9', '#e9f6ee'), MAYBE_GOLD = STRIPE('#fdf1d6', '#f9e4b0'), MAYBE_SOLID = STRIPE('#e8a71c', '#f1bb45');
