    if (moved) out.push({ act: moved.body.split(' · ')[0].replace(/^New date: /, 'Moved to ').replace(/^New time: /, 'New time: ').replace(/^New location: /, 'Now at '), cta: 'See', warn: true, go: () => openToSection(s, 'sec-when') });
