  const ACCT_SEEN_KEY = 'spark-hub-accounts-seen';
  const acctSeenAt = () => { try { return Number(localStorage.getItem(ACCT_SEEN_KEY)) || 0; } catch (e) { return 0; } };
  const loadAccounts = () => sb.rpc('new_accounts')
