    // who hasn't replied gets one quiet card above the RSVP: what Spark Hub is and that RSVPs need no account. No group
    // name (visitors don't see it, v8-8). It goes once they reply; What's Spark Hub? opens the About sheet
    const visitorLine = lead || my || s.cancelledAt || st.viewAs || (st.email && gIds(s).some(g => groupById(g))) ? '' :
      '<div data-visitor-line style="display:flex;gap:12px;align-items:flex-start;padding:14px 16px;border-radius:18px;background:#fff;box-shadow:0 1px 3px rgba(15,18,25,.08)">' +
        '<span aria-hidden="true" style="flex:0 0 34px;width:34px;height:34px;border-radius:999px;background:#fdf1d6;display:flex;align-items:center;justify-content:center">' +
          '<svg width="18" height="18" viewBox="0 0 24 24"><path d="M13.2 2.2 7.2 13.1l3.9-.35-.9 8.8 6.9-11.2-4.1.4z" fill="#e8a71c" stroke="#e8a71c" stroke-width="1.7" stroke-linejoin="round"/></svg></span>' +
        '<div style="flex:1;min-width:0;display:flex;flex-direction:column;gap:4px">' +
          '<span style="font-size:14px;line-height:1.45;font-weight:600;color:#454b55;text-wrap:pretty">Shared with you on <b style="font-weight:800;color:#0d1117">Spark Hub</b>, where people turn ideas into plans. No account needed to RSVP.</span>' +
          '<span ' + on(() => openAbout()) + ' role="button" data-about-link style="align-self:flex-start;display:flex;align-items:center;gap:3px;min-height:32px;font-size:14px;font-weight:800;color:#5b4ae8;cursor:pointer">What’s Spark Hub? ' + I.chevR(12, 'currentColor', 2.8) + '</span></div>' +
      '</div>';
    const guestNudge = st.email || lead || s.cancelledAt || nudgeHidden(s.id) || !(my === 'going' || my === 'maybe' || s.signups.some(it => it.claims.some(c => c.userId === st.me))) ? '' :
      '<div data-guest-nudge style="display:flex;gap:12px;padding:14px 16px;border-radius:18px;background:#f3f1fe">' +
        '<span style="flex:0 0 36px;width:36px;height:36px;border-radius:999px;background:#fff;display:flex;align-items:center;justify-content:center">' + svg(18, stroke('#5b4ae8', 2.2) + ' style="flex:0 0 18px"', '<path d="M7 3.5h10a1 1 0 0 1 1 1v16l-6-4-6 4v-16a1 1 0 0 1 1-1Z"/>') + '</span>' +
        '<div style="flex:1;min-width:0;display:flex;flex-direction:column;gap:4px"><span style="font-size:15.5px;font-weight:900;color:#2a1f8f">Keep this event</span>' +
          '<span style="font-size:13.5px;line-height:1.4;font-weight:600;color:#4a3ad4;text-wrap:pretty">Save it to a free account so you can find it again on any phone or computer.</span>' +
          '<span ' + on(() => openLogin('reminder', () => setTimeout(askReminders, 500))) + ' role="button" style="margin-top:4px;align-self:flex-start;display:flex;align-items:center;min-height:38px;padding:0 16px;border-radius:999px;background:#5b4ae8;color:#fff;font-size:14px;font-weight:800;cursor:pointer">Save to my account</span></div>' +
        '<span ' + on(() => hideNudge(s.id)) + ' aria-label="Not now" role="button" style="flex:0 0 28px;height:28px;display:flex;align-items:center;justify-content:center;color:#8a80e8;cursor:pointer">' + I.x(12, 'currentColor', 2.6) + '</span>' +
      '</div>';
    // Leads answer with the same buttons as everyone (owner, 2026-10-01; the lead is Going to their own plan, 20261101160000)
    // Under the buttons (Design 25b + 25c, 2026-10-03): the going faces and See all ›, opening Who's coming / Who's going;
    // the lead also gets Invite people here (the lead tools card and Who's in's people row are gone)
    const hidden = !st.email && !my && !lead;   // a visitor who hasn't replied sees a count, not who
    // Once you've replied (owner's mock, 2026-10-06): one bar in your answer's colour (You're going · Change) instead of the
