  let lastInput = Date.now(), lastRefresh = 0, refreshFails = 0;
  ['pointerdown', 'keydown', 'touchstart', 'scroll'].forEach(ev => window.addEventListener(ev, () => { lastInput = Date.now(); }, { passive: true, capture: true }));
